namespace eShop.Domain.Entities;

/// <summary>
/// Represents a catalog item in the eShop system
/// </summary>
public class CatalogItem
{
    public const string DefaultPictureName = "dummy.png";

    public CatalogItem()
    {
        PictureFileName = DefaultPictureName;
        CreatedDate = DateTime.UtcNow;
        IsActive = true;
        CreatedBy = "System";
    }

    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string? Description { get; set; }
    public decimal Price { get; set; }
    public string PictureFileName { get; set; }
    public string? PictureUri { get; set; }
    public int CatalogTypeId { get; set; }
    public virtual CatalogType? CatalogType { get; set; }
    public int CatalogBrandId { get; set; }
    public virtual CatalogBrand? CatalogBrand { get; set; }
    public int AvailableStock { get; set; }
    public int RestockThreshold { get; set; }
    public int MaxStockThreshold { get; set; }
    public bool OnReorder { get; set; }
    public DateTime CreatedDate { get; set; }
    public DateTime? ModifiedDate { get; set; }
    public bool IsActive { get; set; }
    public string CreatedBy { get; set; } = string.Empty;
    public string? ModifiedBy { get; set; }
}

namespace eShop.Domain.Entities;

/// <summary>
/// Represents a catalog type/category
/// </summary>
public class CatalogType
{
    public CatalogType()
    {
        CreatedDate = DateTime.UtcNow;
        IsActive = true;
        CreatedBy = "System";
        CatalogItems = new HashSet<CatalogItem>();
    }

    public int Id { get; set; }
    public string Type { get; set; } = string.Empty;
    public DateTime CreatedDate { get; set; }
    public DateTime? ModifiedDate { get; set; }
    public bool IsActive { get; set; }
    public string CreatedBy { get; set; } = string.Empty;
    public string? ModifiedBy { get; set; }
    public virtual ICollection<CatalogItem> CatalogItems { get; set; }
}

namespace eShop.Domain.Entities;

/// <summary>
/// Represents a catalog brand
/// </summary>
public class CatalogBrand
{
    public CatalogBrand()
    {
        CreatedDate = DateTime.UtcNow;
        IsActive = true;
        CreatedBy = "System";
        CatalogItems = new HashSet<CatalogItem>();
    }

    public int Id { get; set; }
